package org.ruoyi.ipd.agent.kernel;
import io.agentscope.core.agent.*;import io.agentscope.core.event.*;import io.agentscope.core.message.*;import io.agentscope.core.model.*;import io.agentscope.core.permission.*;import io.agentscope.core.tool.*;import io.agentscope.harness.agent.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import reactor.core.publisher.*;import static org.mockito.Mockito.*;
public class GHitlProbe{static class Effect extends ToolBase {AtomicInteger executions=new AtomicInteger();Effect(){super(ToolBase.builder().name("g_sideeffect").description("synthetic harmless effect").inputSchema(Map.of("type","object")));}public Mono<ToolResultBlock> callAsync(ToolCallParam p){return Mono.fromSupplier(()->{executions.incrementAndGet();return ToolResultBlock.text("synthetic-executed");});}}
static void run(Path root,boolean wrapped,boolean approve,boolean revoke,boolean wrongSession)throws Exception{String label=wrongSession?"wrapped-wrong-session":wrapped?(revoke?"wrapped-revoked":approve?"wrapped-approved":"wrapped-rejected"):(approve?"native-approved":"native-rejected");AtomicInteger calls=new AtomicInteger();AtomicBoolean live=new AtomicBoolean(true);Model model=new Model(){public String getModelName(){return "no-network-hitl";}public Flux<ChatResponse> stream(List<Msg>m,List<ToolSchema>t,GenerateOptions o){int n=calls.incrementAndGet();if(n==1)return Flux.just(ChatResponse.builder().id("g-response1").content(List.of(ToolUseBlock.builder().id("g-pending").name("g_sideeffect").input(Map.of()).content("{}").build())).finishReason("tool_calls").build());return Flux.just(ChatResponse.builder().id("g-response"+n).content(List.of(TextBlock.builder().text("synthetic-followup").build())).finishReason("stop").build());}};Effect effect=new Effect();Toolkit toolkit=new Toolkit();toolkit.registerAgentTool(effect);var access=mock(org.ruoyi.ipd.service.IpdCopilotAccess.class);var actor=mock(org.ruoyi.ipd.security.IpdActor.class);when(access.requireVisible(actor,123L)).thenAnswer(i->{if(!live.get())throw new IllegalStateException("membership-revoked");return "synthetic-tenant";});var membership=new ProjectAgentRuntimeAccess(access,actor,123L);var sink=mock(ProjectAgentEventSink.class);doAnswer(i->{membership.requireAuthorized();return null;}).when(sink).requireActiveOwnership();var builder=HarnessAgent.builder().name("g-hitl-"+label).workspace(root.resolve(label)).model(model).toolkit(toolkit).stateStore(new io.agentscope.core.state.InMemoryAgentStateStore()).permissionContext(PermissionContextState.builder().addAskRule("g_sideeffect",new PermissionRule("g_sideeffect",null,PermissionBehavior.ASK,"synthetic owner approval")).build());if(wrapped)builder.middleware(new ProjectAgentOfficialToolGovernance(sink));var agent=builder.build();if(wrapped)new ProjectAgentOfficialToolGovernance(sink).bind(agent.getToolkit());var rc=RuntimeContext.builder().userId("synthetic-person").sessionId("g-hitl-"+label).build();try{var first=agent.streamEvents(Msg.builder().role(MsgRole.USER).textContent("Synthetic effect request").build(),rc).collectList().block(java.time.Duration.ofSeconds(10));RequireUserConfirmEvent ask=first.stream().filter(e->e instanceof RequireUserConfirmEvent).map(e->(RequireUserConfirmEvent)e).findFirst().orElseThrow();if(effect.executions.get()!=0)throw new AssertionError("executed before confirmation");System.out.println(label+".REQUIRE_CONFIRM=true");System.out.println(label+".BEFORE_EFFECTS="+effect.executions.get());if(revoke)live.set(false);var follow=Msg.builder().role(MsgRole.USER).textContent("Synthetic decision").metadata(Map.of(Msg.METADATA_CONFIRM_RESULTS,List.of(new ConfirmResult(approve,ask.getToolCalls().get(0))))).build();try{var resumed=agent.streamEvents(follow,wrongSession?RuntimeContext.builder().userId("synthetic-person").sessionId("different-session").build():rc).collectList().block(java.time.Duration.ofSeconds(10));for(var event:resumed)if(event instanceof ToolResultEndEvent end)System.out.println(label+".RESULT_STATE="+end.getState());System.out.println(label+".USER_CONFIRM_EVENT="+resumed.stream().anyMatch(e->e instanceof UserConfirmResultEvent));}catch(Exception error){System.out.println(label+".RESUME_ERROR_TYPE="+error.getClass().getSimpleName());}System.out.println(label+".AFTER_EFFECTS="+effect.executions.get());if(!wrapped&&approve&&effect.executions.get()!=1)throw new AssertionError("native approve did not execute");if((!approve||revoke||wrongSession)&&effect.executions.get()!=0)throw new AssertionError("negative executed");}finally{agent.close();}}public static void main(String[]a)throws Exception{Path p=Path.of(a[0]);run(p,false,true,false,false);run(p,false,false,false,false);run(p,true,true,false,false);run(p,true,false,false,false);run(p,true,true,true,false);run(p,true,true,false,true);}}
